create or replace function public.append_shared_action_event(p_id uuid,p_episode_id uuid,p_property_id uuid,p_actor_id uuid,p_product text,p_action text,p_evidence text,p_phase text,p_request jsonb,p_before jsonb,p_after jsonb,p_result jsonb,p_links jsonb default '{}')
returns jsonb language plpgsql security invoker set search_path='' as $$
declare organization uuid;e public.shared_action_events;episode public.shared_action_episodes;origin text;job uuid;attempt uuid;context_id uuid;
begin
 if p_id is null or p_episode_id is null or p_actor_id is null or jsonb_typeof(p_request) is distinct from 'object' or jsonb_typeof(p_result) is distinct from 'object'
  or length(coalesce(p_request::text,''))+length(coalesce(p_before::text,''))+length(coalesce(p_after::text,''))+length(coalesce(p_result::text,''))>32768 then raise exception 'Invalid action event';end if;
 if p_product not in ('platform','siteforge','lumaleasing','propertyaudit','brandforge','tourspark','leadpulse','crm','forgestudio','reviewflow','marketvision','bi','knowledge','property','integrations','reports','pipelines','settings','team','agency')
  or p_action not in ('market.alert.created','market.alert.read','market.alert.dismissed','market.alert.restored','market.intake.prepared','market.intake.applied','market.intake.stopped','market.handoff.prepared','market.handoff.decided','market.brief.requested','market.brief.recovered','market.brief.reviewed','market.brief.exported','market.source.requested','market.source.stopped','market.source.recovered','market.listing.saved','market.listing.removed','market.extraction.requested','market.extraction.stopped','market.extraction.recovered','market.extraction.rebased','market.extraction.applied','market.competitor.saved','market.competitor.archived','market.competitor.restored','market.unit.saved','market.unit.removed','market.configuration.saved','review.testimonial.approved','review.testimonial.revoked','review.insights.saved','review.batch.prepared','review.batch.approved','review.batch.stopped','review.batch.recovered','review.configuration.saved','review.connection.saved','review.connection.disconnected','review.intake.requested','review.intake.applied','review.intake.stopped','review.intake.recovered','review.intake.rebased','review.publication.prepared','review.publication.reported','review.publication.cancelled','review.publication.uncertain','review.response.draft_saved','review.response.approved','review.response.rejected','review.response.generation_requested','review.response.generation_started','review.response.generation_result_received','review.response.generation_completed','review.response.generation_stopped','review.response.generation_recovered','review.case.created','review.case.updated','review.case.resolved','review.case.dismissed','review.case.reopened','review.case.note_added','review.ticket.created','review.ticket.updated','review.ticket.reopened','review.analysis.started','review.analysis.result_received','review.analysis.requested','review.analysis.completed','review.analysis.stopped','review.analysis.recovered','studio.credentials.renewal_requested','studio.credentials.renewal_completed','studio.app_configuration.save','studio.app_configuration.disable','studio.connection.disconnected','studio.authorization.started','studio.authorization.cancelled','studio.authorization.applied','studio.configuration.saved','studio.metrics.requested','studio.metrics.reported','studio.metrics.reviewed','studio.attribution.reviewed','studio.media.requested','studio.media.stopped','studio.media.recovered','studio.media.completed','studio.asset.saved','studio.asset.reviewed','studio.asset.archived','studio.asset.restored','studio.asset.upload.requested','studio.asset.uploaded','studio.asset.replaced','studio.asset.upload.recovered','studio.sources.refreshed','studio.generation.recovered','studio.generation.requested','studio.generation.stopped','studio.publication.recovery_reviewed','studio.publications.scheduled','studio.publication.cancel','studio.publication.reschedule','studio.brief.saved','studio.package.created','studio.revision.saved','studio.revision.reviewed','crm.qualification.prepared','crm.qualification.approved','crm.qualification.recovered','crm.qualification.activated','crm.qualification.stopped','crm.qualification.completed','crm.bulk.prepared','crm.bulk.approved','crm.bulk.stopped','crm.delivery.recovery_requested','crm.delivery.recovery_checked','crm.delivery.approved','crm.delivery.requested','crm.delivery.completed','crm.delivery.cancelled','crm.delivery.reconciled','crm.mapping.saved','crm.mapping.previewed','crm.mapping.approved','crm.operation.requested','crm.operation.completed','crm.operation.stopped','lead.score.reviewed','lead.engagement.recorded','lead.engagement.corrected','lead.score.recalculated','lead.scoring.started','lead.scoring.completed','lead.scoring.cancelled','console.page.viewed','workflow.pause','workflow.resume','workflow.stop','workflow.delivery.reviewed','tour.outcome.recorded','tour.no_show.corrected','tour.rescheduled','tour.cancelled','tour.reminder.reviewed','tour.booked','tour.timezone.set','tour.schedule_delivery.reviewed','tour.calendar_change.reviewed','tour.calendar_event.bound','brand.research.requested','brand.research.completed','brand.research.cancelled','brand.source.saved','brand.asset.upload.requested','brand.asset.uploaded','brand.asset.reviewed','brand.import.previewed','brand.operation.requested','brand.operation.cancelled','brand.brief.saved','brand.section.generated','brand.section.regenerated','brand.section.edited','brand.section.approved','brand.contract.generated','brand.contract.imported','brand.export.created','brand.revision.started','brand.visuals.generated','brand.knowledge.published','calendar.disconnected','integration.authorization.completed','integration.authorization.started','integration.authorization.cancelled','integration.authorization.failed','email.disconnected','integration.invite.created','integration.invite.revoked','integration.replacement.requested','integration.account.replaced','luma.configuration.created','luma.configuration.saved') then raise exception 'Unregistered action';end if;
 if p_action='console.page.viewed' then
  if p_evidence<>'browser_observed' or p_phase<>'observed' or p_request-array['path']<>'{}' or p_before is not null or p_after is not null or p_links<>'{}' then raise exception 'Invalid observation';end if;
 elsif p_action in ('calendar.disconnected','integration.authorization.completed','integration.authorization.started','integration.authorization.cancelled','integration.authorization.failed','email.disconnected','integration.invite.created','integration.invite.revoked','integration.replacement.requested','integration.account.replaced') then
  if p_product<>'integrations' or p_evidence<>'server_confirmed' or p_phase not in ('succeeded','failed') then raise exception 'Invalid connection evidence';end if;
 elsif p_action like 'review.%' then
  if p_product<>'reviewflow' or p_evidence<>'server_confirmed' or p_phase not in('succeeded','failed') then raise exception 'Invalid review evidence';end if;
 elsif p_action like 'market.%' then
  if p_product<>'marketvision' or p_evidence<>'server_confirmed' or p_phase<>'succeeded' then raise exception 'Invalid market evidence';end if;
 elsif p_action like 'studio.%' then
  if p_product<>'forgestudio' or p_evidence<>'server_confirmed' or p_phase not in ('succeeded','failed') then raise exception 'Invalid editorial evidence';end if;
 elsif p_action like 'crm.%' then
  if p_product<>'crm' or p_evidence<>'server_confirmed' or p_phase not in ('succeeded','failed') then raise exception 'Invalid CRM evidence';end if;
 elsif p_action like 'lead.%' then
  if p_product<>'leadpulse' or p_evidence<>'server_confirmed' or p_phase not in ('succeeded','failed') then raise exception 'Invalid scoring evidence';end if;
 elsif p_action like 'brand.%' then
  if p_product<>'brandforge' or p_evidence<>'server_confirmed' or p_phase not in ('succeeded','failed') then raise exception 'Invalid brand evidence';end if;
 elsif p_action in ('luma.configuration.created','luma.configuration.saved') then
  if p_product<>'lumaleasing' or p_evidence<>'server_confirmed' or p_phase not in ('succeeded','failed') then raise exception 'Invalid configuration evidence';end if;
 else
  if p_product<>'tourspark' or p_evidence<>'server_confirmed' or p_phase not in ('succeeded','failed') then raise exception 'Invalid workflow evidence';end if;
 end if;
 select p.org_id into organization from public.properties p join public.profiles u on p.org_id=u.org_id where p.id=p_property_id and u.id=p_actor_id;
 if organization is null then return '{"state":"forbidden"}';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_property_id::text,12));
 job:=nullif(p_links->>'jobId','')::uuid;attempt:=nullif(p_links->>'attemptId','')::uuid;context_id:=nullif(p_links->>'contextId','')::uuid;
 select * into e from public.shared_action_events where id=p_id;
 if found then
  if (e.episode_id,e.property_id,e.actor_id,e.product,e.action,e.evidence,e.phase,e.request,e.before_state,e.after_state,e.result,e.shared_job_ref,e.shared_attempt_ref,e.context_snapshot_ref)
   is distinct from (p_episode_id,p_property_id,p_actor_id,p_product,p_action,p_evidence,p_phase,p_request,p_before,p_after,p_result,job,attempt,context_id) then return '{"state":"request_conflict"}';end if;
  return jsonb_build_object('state','replayed','eventId',e.id);
 end if;
 if job is not null and not exists(select 1 from public.shared_jobs where id=job and org_id=organization and property_id=p_property_id) then return '{"state":"link_conflict"}';end if;
 if attempt is not null and not exists(select 1 from public.shared_action_attempts where id=attempt and org_id=organization and property_id=p_property_id and (job is null or job_id=job)) then return '{"state":"link_conflict"}';end if;
 if context_id is not null and not exists(select 1 from public.shared_context_snapshots where id=context_id and org_id=organization and property_id=p_property_id) then return '{"state":"link_conflict"}';end if;
 origin:=case when p_action like 'market.%' then 'console' when p_action in('review.response.generation_started','review.response.generation_result_received','review.response.generation_completed') or(p_action='review.response.draft_saved' and p_result->>'origin'='model_result') then 'workflow' when p_action in('review.analysis.started','review.analysis.result_received','review.analysis.completed') then 'workflow' when p_action like 'review.%' then 'console' when p_action in('studio.media.completed','studio.credentials.renewal_completed') then 'workflow' when p_action like 'studio.%' then 'console' when p_action like 'lead.%' or p_action like 'crm.%' then 'console' when p_action in ('console.page.viewed','luma.configuration.created','luma.configuration.saved') then 'console' else 'workflow' end;
 insert into public.shared_action_episodes(id,org_id,property_id,actor_id,origin)values(p_episode_id,organization,p_property_id,p_actor_id,origin) on conflict(id) do nothing;
 select * into episode from public.shared_action_episodes where id=p_episode_id;
 if (episode.org_id,episode.property_id,episode.actor_id,episode.origin) is distinct from (organization,p_property_id,p_actor_id,origin) then return '{"state":"episode_conflict"}';end if;
 insert into public.shared_action_events(id,episode_id,org_id,property_id,actor_id,product,action,evidence,phase,request,before_state,after_state,result,shared_job_ref,shared_attempt_ref,context_snapshot_ref)
 values(p_id,p_episode_id,organization,p_property_id,p_actor_id,p_product,p_action,p_evidence,p_phase,p_request,p_before,p_after,p_result,job,attempt,context_id);
 return jsonb_build_object('state','recorded','eventId',p_id);
end; $$;

alter table public.market_alerts add column version integer not null default 1;
create index marketvision_alert_keyset on public.market_alerts(property_id,coalesce(created_at,'epoch'::timestamptz)desc,id desc);
create function public.guard_marketvision_alert_version()returns trigger language plpgsql security invoker set search_path=''as $$begin
 new.version:=case when(to_jsonb(new)-'version')is distinct from(to_jsonb(old)-'version')then old.version+1 else old.version end;return new;
end$$;
create trigger marketvision_alert_version before update on public.market_alerts for each row execute function public.guard_marketvision_alert_version();
revoke all on public.market_alerts from public,anon,authenticated;
grant all on public.market_alerts to service_role;

create function public.marketvision_alert_summary(p_alert public.market_alerts)returns jsonb language sql stable security invoker set search_path=''as $$
 select jsonb_build_object('id',p_alert.id,'version',p_alert.version,'competitorId',p_alert.competitor_id,'competitorName',(select name from public.competitors where id=p_alert.competitor_id and property_id=p_alert.property_id),'alertType',p_alert.alert_type,'severity',coalesce(p_alert.severity,'unknown'),'title',p_alert.title,'description',p_alert.description,'isRead',coalesce(p_alert.is_read,false),'isDismissed',coalesce(p_alert.is_dismissed,false),'readAt',p_alert.read_at,'createdAt',p_alert.created_at,'source',case when exists(select 1 from public.marketvision_decisions d where d.property_id=p_alert.property_id and d.id=(case when p_alert.data->>'decisionId'~*'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'then(p_alert.data->>'decisionId')::uuid end)and((d.kind='alert.created'and d.resource_id=p_alert.id)or(d.kind='competitor.saved'and d.resource_id=p_alert.competitor_id)))then 'operator_reported'else 'historical_unverified'end);
$$;

create function public.create_marketvision_alert(p_id uuid,p_property_id uuid,p_actor_id uuid,p_input jsonb)returns jsonb language plpgsql security invoker set search_path=''as $$
declare prior jsonb;entry public.market_alerts;begin
 prior:=public.marketvision_decision_start(p_id,p_property_id,p_actor_id,'alert.created',p_input);if prior->>'state'<>'new'then return prior;end if;
 if(p_input-array['title','description','severity','competitorId','reason'])<>'{}'or jsonb_typeof(p_input->'title')is distinct from 'string'or length(trim(p_input->>'title'))not between 1 and 300 or length(coalesce(p_input->>'description',''))>4000 or coalesce(p_input->>'severity','')not in('info','warning','critical')then raise exception 'Review the reported alert details';end if;
 if nullif(p_input->>'competitorId','')is not null and not exists(select 1 from public.competitors where id=(p_input->>'competitorId')::uuid and property_id=p_property_id)then return '{"state":"not_found"}';end if;
 insert into public.market_alerts(id,property_id,competitor_id,alert_type,severity,title,description,data)values(p_id,p_property_id,nullif(p_input->>'competitorId','')::uuid,'competitor_update',p_input->>'severity',trim(p_input->>'title'),nullif(p_input->>'description',''),jsonb_build_object('source','operator_reported','decisionId',p_id))returning *into entry;
 return public.marketvision_decision_finish(p_id,p_property_id,p_actor_id,'alert.created',entry.id,p_input,null,public.marketvision_alert_summary(entry)||'{"source":"operator_reported"}',jsonb_build_object('alertIds',jsonb_build_array(entry.id),'changed',1,'providerVerified',false,'externalExecutionStarted',false));
end$$;

create function public.review_marketvision_alerts(p_id uuid,p_property_id uuid,p_actor_id uuid,p_input jsonb)returns jsonb language plpgsql security invoker set search_path=''as $$
declare prior jsonb;kind text;item jsonb;entry public.market_alerts;before_rows jsonb:='[]';after_rows jsonb:='[]';ids jsonb:='[]';changed integer:=0;first_id uuid;begin
 kind:=case p_input->>'action'when 'read'then 'alert.read'when 'dismiss'then 'alert.dismissed'when 'restore'then 'alert.restored'end;if kind is null then raise exception 'Choose read, dismiss or restore';end if;
 prior:=public.marketvision_decision_start(p_id,p_property_id,p_actor_id,kind,p_input);if prior->>'state'<>'new'then return prior;end if;
 if(p_input-array['action','alerts','reason'])<>'{}'or jsonb_typeof(p_input->'alerts')is distinct from 'array'or jsonb_array_length(p_input->'alerts')not between 1 and 50 or(select count(distinct value->>'id')from jsonb_array_elements(p_input->'alerts'))<>jsonb_array_length(p_input->'alerts')then raise exception 'Review one to 50 unique displayed alerts';end if;
 -- Lock every row in consistent order, and validate the entire displayed selection before changes.
 for item in select value from jsonb_array_elements(p_input->'alerts')order by value->>'id'loop
  if(item-array['id','expectedVersion'])<>'{}'then raise exception 'Only review displayed alert identities and versions';end if;
  select *into entry from public.market_alerts where id=(item->>'id')::uuid and property_id=p_property_id for update;if not found then return '{"state":"not_found"}';end if;
  if entry.version is distinct from(item->>'expectedVersion')::integer then return '{"state":"stale_alert"}';end if;
  if(kind='alert.read'and(coalesce(entry.is_read,false)or coalesce(entry.is_dismissed,false)))or(kind='alert.dismissed'and coalesce(entry.is_dismissed,false))or(kind='alert.restored'and not coalesce(entry.is_dismissed,false))then return '{"state":"alert_state_changed"}';end if;
  first_id:=coalesce(first_id,entry.id);ids:=ids||jsonb_build_array(entry.id);
  before_rows:=before_rows||jsonb_build_array(jsonb_build_object('id',entry.id,'version',entry.version,'isRead',coalesce(entry.is_read,false),'isDismissed',coalesce(entry.is_dismissed,false),'readAt',entry.read_at,'contentHash',public.crm_configuration_hash(to_jsonb(entry)-array['version','is_read','is_dismissed','read_at'])));
 end loop;
 for item in select value from jsonb_array_elements(p_input->'alerts')order by value->>'id'loop
  update public.market_alerts set is_read=case when kind='alert.read'then true else is_read end,read_at=case when kind='alert.read'then clock_timestamp()else read_at end,is_dismissed=case when kind='alert.dismissed'then true when kind='alert.restored'then false else is_dismissed end where id=(item->>'id')::uuid and property_id=p_property_id returning *into entry;
  changed:=changed+1;after_rows:=after_rows||jsonb_build_array(jsonb_build_object('id',entry.id,'version',entry.version,'isRead',coalesce(entry.is_read,false),'isDismissed',coalesce(entry.is_dismissed,false),'readAt',entry.read_at));
 end loop;
 return public.marketvision_decision_finish(p_id,p_property_id,p_actor_id,kind,first_id,p_input,jsonb_build_object('alerts',before_rows),jsonb_build_object('alerts',after_rows),jsonb_build_object('alertIds',ids,'changed',changed,'sourceVerified',false,'externalExecutionStarted',false));
end$$;

create function public.read_marketvision_alerts(p_property_id uuid,p_actor_id uuid,p_view text default 'open',p_cursor uuid default null,p_limit integer default 20)returns jsonb language plpgsql stable security invoker set search_path=''as $$
declare organization uuid;anchor timestamptz;items jsonb;counts jsonb;begin
 select p.org_id into organization from public.properties p join public.profiles a on a.org_id=p.org_id where p.id=p_property_id and a.id=p_actor_id;if not found then return '{"state":"forbidden"}';end if;
 if p_view not in('open','unread','dismissed','all')or p_view is null or p_limit not between 1 and 50 or p_limit is null then raise exception 'Choose a valid alert view and page size';end if;
 if p_cursor is not null then select coalesce(created_at,'epoch'::timestamptz)into anchor from public.market_alerts where id=p_cursor and property_id=p_property_id;if not found then return '{"state":"cursor_changed"}';end if;end if;
 with all_rows as materialized(select *from public.market_alerts where property_id=p_property_id),page as(select *from all_rows a where(p_view='all'or(p_view='open'and not coalesce(a.is_dismissed,false))or(p_view='unread'and not coalesce(a.is_read,false)and not coalesce(a.is_dismissed,false))or(p_view='dismissed'and coalesce(a.is_dismissed,false)))and(p_cursor is null or(coalesce(a.created_at,'epoch'::timestamptz),a.id)<(anchor,p_cursor))order by coalesce(a.created_at,'epoch'::timestamptz)desc,a.id desc limit p_limit+1)
 select(select coalesce(jsonb_agg(public.marketvision_alert_summary(p)order by coalesce(p.created_at,'epoch'::timestamptz)desc,p.id desc),'[]')from page p),(select jsonb_build_object('all',count(*),'open',count(*)filter(where not coalesce(is_dismissed,false)),'unread',count(*)filter(where not coalesce(is_dismissed,false)and not coalesce(is_read,false)),'dismissed',count(*)filter(where coalesce(is_dismissed,false)))from all_rows)into items,counts;
 return jsonb_build_object('state','ready','alerts',case when jsonb_array_length(items)>p_limit then items-p_limit else items end,'nextCursor',case when jsonb_array_length(items)>p_limit then items->(p_limit-1)->>'id'else null end,'counts',counts,'readAt',statement_timestamp());
end$$;
revoke all on function public.guard_marketvision_alert_version(),public.marketvision_alert_summary(public.market_alerts),public.create_marketvision_alert(uuid,uuid,uuid,jsonb),public.review_marketvision_alerts(uuid,uuid,uuid,jsonb),public.read_marketvision_alerts(uuid,uuid,text,uuid,integer)from public,anon,authenticated;
grant execute on function public.marketvision_alert_summary(public.market_alerts),public.create_marketvision_alert(uuid,uuid,uuid,jsonb),public.review_marketvision_alerts(uuid,uuid,uuid,jsonb),public.read_marketvision_alerts(uuid,uuid,text,uuid,integer)to service_role;
